{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_and_empty():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty():
    groups = {"a": [event("a", 1, True)],
              "b": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 1) == 0


def test_parse_log_skips_lines_and_parses_all_flag_values():
    lines = ["\n", "   \t", "  # comment,with,commas", " x , 2 , 1 \n",
             "y, -1, 0", "z,3,  "]
    assert parse_transcript_log(lines) == [event("x", 2, True),
                                           event("y", -1, False),
                                           event("z", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1,yes"])
def test_parse_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "# comment", "a,1,1", bad_line])


def test_dedupe_keeps_last_record_for_duplicate_ids_and_sorts():
    events = [event("a", 0, True), event("b", 2, False), event("a", 2, None),
              event("c", 1, True), event("b", 2, True)]
    assert dedupe_transcripts(events) == [events[3], events[2], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_gaps():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)], "empty": [],
              "b": [event("b", 4, True), event("c", 4, False), event("d", 4, False),
                    event("e", 4, False), event("f", 4, False)]}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    result = flag_rate_by_group({"z": [], "b": [event("b", 1, False)],
                                 "a": [event("a", 1, True)]})
    assert list(result.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_flag_streak_resets_and_requires_positive_entries():
    assert longest_flag_streak([1, 1, 0, 2, 3, 4, -1, 1]) == 3
    assert longest_flag_streak([0, -2, 0]) == 0
    assert longest_flag_streak([]) == 0
